
const baseURL = document.querySelector("meta[name='base-url']").getAttribute("content");
const resourcesURL = baseURL + "/resources";

var page = window.location.pathname.split("/").pop().split(".")[0],
    aux = window.location.pathname.split("/"),
    root = window.location.pathname.split("/");

function loadJS(src, async = true) {
    let script = document.createElement("script");
    script.src = src;
    script.type = "text/javascript";
    script.async = async;
    document.head.appendChild(script);
}

function loadStylesheet(href) {
    let link = document.createElement("link");
    link.href = href;
    link.type = "text/css";
    link.rel = "stylesheet";
    document.head.appendChild(link);
}

if (!aux.includes("pages")) {
    page = "dashboard";
}

// Carregamento de recursos usando baseURL/resources
loadStylesheet(resourcesURL + "/assets/css/perfect-scrollbar.css");
loadJS(resourcesURL + "/assets/js/perfect-scrollbar.js");

if (document.querySelector("[slider]")) {
    loadJS(resourcesURL + "/assets/js/carousel.js");
}

if (document.querySelector("nav [navbar-trigger]")) {
    loadJS(resourcesURL + "/assets/js/navbar-collapse.js");
}

if (document.querySelector("[data-target='tooltip']")) {
    loadJS(resourcesURL + "/assets/js/tooltips.js");
    loadStylesheet(resourcesURL + "/assets/css/tooltips.css");
}

if (document.querySelector("[nav-pills]")) {
    loadJS(resourcesURL + "/assets/js/nav-pills.js");
}

if (document.querySelector("[dropdown-trigger]")) {
    loadJS(resourcesURL + "/assets/js/dropdown.js");
}

if (document.querySelector("[fixed-plugin]")) {
    loadJS(resourcesURL + "/assets/js/fixed-plugin.js");
}

if (document.querySelector("[navbar-main]") || document.querySelector("[navbar-profile]")) {
    if (document.querySelector("[navbar-main]")) {
        loadJS(resourcesURL + "/assets/js/navbar-sticky.js");
    }
    if (document.querySelector("aside")) {
        loadJS(resourcesURL + "/assets/js/sidenav-burger.js");
    }
}

if (document.querySelector("canvas")) {
    loadJS(resourcesURL + "/assets/js/charts.js");
}

if (document.querySelector(".github-button")) {
    loadJS("https://buttons.github.io/buttons.js");
}

